import json, time, urllib.request, urllib.error, datetime, decimal
BASE='http://localhost:8080'
def get_json(path, token=None):
    req=urllib.request.Request(BASE+path, headers={'Authorization':'Bearer '+token} if token else {})
    try:
        with urllib.request.urlopen(req, timeout=20) as response:
            return json.loads(response.read())
    except urllib.error.HTTPError as e:
        raise

def fresh_token():
    while True:
        try: return get_json('/token')['token']
        except urllib.error.HTTPError as e:
            if e.code==429:
                time.sleep(float(e.headers.get('Retry-After','1'))); continue
            raise

token=[REDACTED_SECRET]
all_rows=[]
path='/orders?page=1'
page_total=None
while path:
    while True:
        try:
            payload=get_json(path,token)
            break
        except urllib.error.HTTPError as e:
            if e.code==429:
                time.sleep(float(e.headers.get('Retry-After','1')))
                continue
            if e.code in (401,403):
                token=[REDACTED_SECRET]
                continue
            raise
    if page_total is None: page_total=payload['total_pages']
    if payload['total_pages'] "'!= page_total: raise RuntimeError('"'total_pages changed')
    all_rows.extend(payload['items'])
    print(f\"page {payload['page']}/{page_total}: {len(payload['items'])} items\", flush=True)
    path=payload['next']

seen={}; duplicates=0
for order in all_rows:
    oid=order['id']
    if oid in seen:
        duplicates+=1
        if seen[oid] "'!= order: raise RuntimeError(f'"'Conflicting duplicate {oid}')
    else: seen[oid]=order

start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
qualifying=[]
for o in seen.values():
    dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if o['status']=='shipped' and start <= dt < end: qualifying.append(o)

customers={}
for cid in sorted({o['customer_id'] for o in qualifying}):
    while True:
        try:
            customers[cid]=get_json('/customers/'+cid,token)
            break
        except urllib.error.HTTPError as e:
            if e.code==429:
                time.sleep(float(e.headers.get('Retry-After','1'))); continue
            if e.code in (401,403):
                token=[REDACTED_SECRET] continue
            raise

regions={r:0 for r in ('north','south','east','west')}
for o in qualifying:
    c=customers[o['customer_id']]
    # Integer half-up: amount*(100-discount)/100, with exact .5 rounded upward.
    n=o['amount_cents']*(100-c['discount_pct'])
    discounted=(2*n+100)//200
    regions[c['region']]+=discounted
result={'total_cents':sum(regions.values()),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':regions}
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps({'rows_listed':len(all_rows),'unique_orders':len(seen),'qualifying':len(qualifying),'unique_customers':len(customers),'result':result},indent=2))
